import { Schema } from "effect"
import { Norn } from "@norn/authoring"

// The demo's analytics table: one row per order line, with the columns the
// ERP exports do not carry. Generated by demo/data/generate.py (orders.json)
// and loaded through the governed action route. Quantities come in several
// units (g, kg, piece): a sum of `quantity` is meaningful only per unit.
export const Order = Norn.type({
  name: "sales.Order", title: "Order line (analytics)", version: "0.1.0",
  properties: Schema.Struct({
    order_ref: Schema.String,
    order_date: Schema.String,
    ship_date: Schema.String,
    lead_time_days: Schema.Int,
    customer_ref: Schema.String,
    segment: Schema.Literals(["retail", "wholesale", "enterprise"]),
    region: Schema.Literals(["north", "south", "east", "west"]),
    item_code: Schema.String,
    quantity: Norn.decimal(0),
    unit: Schema.Literals(["g", "kg", "piece"]),
    unit_price: Norn.decimal(2),
    currency: Schema.Literals(["USD"]),
    system: Schema.Literals(["erpnext", "shopify", "odoo"]),
  }),
  identity: [{ name: "primary", properties: ["order_ref"] }],
})

export const AddOrder = Norn.action({
  id: "sales.order.add", title: "Add order line", version: "0.1.0",
  input: Schema.Struct({
    order_ref: Schema.String, order_date: Schema.String, ship_date: Schema.String, lead_time_days: Schema.Int,
    customer_ref: Schema.String, segment: Schema.Literals(["retail", "wholesale", "enterprise"]),
    region: Schema.Literals(["north", "south", "east", "west"]), item_code: Schema.String,
    quantity: Norn.decimal(0), unit: Schema.Literals(["g", "kg", "piece"]), unit_price: Norn.decimal(2),
    currency: Schema.Literals(["USD"]), system: Schema.Literals(["erpnext", "shopify", "odoo"]),
  }),
  output: Schema.Struct({ order_ref: Schema.String }),
  scopeRequired: ["orgId", "environmentId"], idempotent: true, ledgered: true,
  // A data contract enforced at write time: no negative or zero lines, and a
  // ship date on or after the order date.
  preconditions: [
    Norn.unsafeZen<boolean>("input.quantity > 0 and input.unit_price >= 0 and input.lead_time_days >= 0"),
  ],
  writes: [{ type: Order, change: "created" }],
  effect: { kind: "upsert_input_object", type: Order, objectIdField: "order_ref", writeMode: { kind: "create_only" } },
})
